import json

# Load the JSON file and look for the table with corporate bond yields
with open('/app/resources/treasury_bulletin_2003_03.json', 'r') as f:
    data = json.load(f)

# Look for tables containing "Aa corporate" or similar
def search_nested(obj, target, depth=0):
    if depth > 10:
        return
    if isinstance(obj, dict):
        for key, value in obj.items():
            if target.lower() in str(key).lower():
                print(f"Found at depth {depth}: {key}")
            search_nested(value, target, depth+1)
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:10]):
            search_nested(item, target, depth+1)

search_nested(data, "MY-2")
